//! 🎟️ The real history frame constructor keeps original pointers until its exact admission.
use super::{admit_history_read_retirement,history_read_retirement_birth_bytes};
use super::super::{ArtifactDerivedHistoryPreview,HistoryReadPlan,ReplayProgress,SnapshotReadLeaseRegistry,artifact_retirement_box_close_step,artifact_retirement_box_demands,fixture_mutations::demo::DemoMutation,tests::DemoSnapshot};
use semio_framework_value::{ArtifactOwnedValueRetirementFactory,retirement::OwnedValueRetirementFactory,retained_clone::{RetainedCloneGrant,RetainedCloneProgress},ValueRefusalKind};
use semio_framework_trace::observe_heap_allocations_on_this_thread;
use std::{sync::Arc,marker::PhantomData};

#[test]
fn history_read_prepared_derived_snapshot_conserves_original_registry_and_payload(){
 use semio_framework_value::ErasedSnapshotRetirement;
 let ((mut original,snapshots,mutations),heap)=observe_heap_allocations_on_this_thread(||{let original=Some(super::super::ArtifactDerivedSnapshot{owner:Arc::new(DemoSnapshot{n:Some(23)}),registry:crate::os_store::SnapshotReadRegistryHandle::new(),generation:7,revision:[11;32]});let snapshots:Arc<dyn ArtifactOwnedValueRetirementFactory<DemoSnapshot>>=Arc::new(OwnedValueRetirementFactory::<DemoSnapshot>::default());let mutations:Arc<dyn ArtifactOwnedValueRetirementFactory<DemoMutation>>=Arc::new(OwnedValueRetirementFactory::<DemoMutation>::default());(original,snapshots,mutations)});let held=heap.requested_bytes-heap.released_bytes;let pointer=Arc::as_ptr(&original.as_ref().unwrap().owner);let registry=original.as_ref().unwrap().registry.identity();
 let grant=RetainedCloneGrant{maximum_items:1,maximum_copy_bytes:4096,maximum_capacity_bytes:8192,maximum_release_bytes:262144,maximum_depth:128};let ((mut prepared,receipt),heap)=observe_heap_allocations_on_this_thread(||super::prepare_history_read_retirement(&snapshots,&mutations,grant).unwrap().unwrap());assert!(receipt.fits(grant));assert_eq!((heap.requested_bytes,heap.released_bytes),(receipt.retained_capacity_bytes,receipt.released_bytes));let mut births=heap.requested_bytes;let mut releases=heap.released_bytes;
 for denied in [RetainedCloneGrant{maximum_items:0,..grant},RetainedCloneGrant{maximum_depth:0,..grant}]{let (receipt,heap)=observe_heap_allocations_on_this_thread(||prepared.install_derived_snapshot(&mut original,denied).unwrap());assert!(receipt.is_none());assert_eq!((heap.requested_bytes,heap.released_bytes),(0,0));assert_eq!(Arc::as_ptr(&original.as_ref().unwrap().owner),pointer);assert_eq!(original.as_ref().unwrap().registry.identity(),registry)}
 prepared.bind_registry(registry.wrapping_add(1));let (refused,heap)=observe_heap_allocations_on_this_thread(||prepared.install_derived_snapshot(&mut original,grant));assert!(refused.is_err());assert_eq!((heap.requested_bytes,heap.released_bytes),(0,0));assert_eq!(Arc::as_ptr(&original.as_ref().unwrap().owner),pointer);prepared.bind_registry(registry);let (receipt,heap)=observe_heap_allocations_on_this_thread(||prepared.install_derived_snapshot(&mut original,grant).unwrap().unwrap());assert!(receipt.fits(grant));assert_eq!((heap.requested_bytes,heap.released_bytes),(0,0));assert!(original.is_none());let (_,heap)=observe_heap_allocations_on_this_thread(||drop((snapshots,mutations)));assert_eq!((heap.requested_bytes,heap.released_bytes),(0,0));
 for _ in 0..10000{if prepared.terminal_is_empty(){break}let (step,heap)=observe_heap_allocations_on_this_thread(||prepared.close_step(grant).unwrap());assert!(step.progress().fits(grant));assert_eq!((heap.requested_bytes,heap.released_bytes),(step.progress().retained_capacity_bytes,step.progress().released_bytes));births+=heap.requested_bytes;releases+=heap.released_bytes}assert!(prepared.terminal_is_empty());assert_eq!(releases,held+births);let (_,heap)=observe_heap_allocations_on_this_thread(||drop((prepared,original)));assert_eq!((heap.requested_bytes,heap.released_bytes),(0,0));eprintln!("[DEBUG] actual derived snapshot and original registry original={held} births={births} releases={releases} deniedCustody=stable terminalDrop=0");
}
#[test]
fn history_read_retirement_frame_preserves_original_preview_on_every_refusal() {
    let law:serde_json::Value=serde_json::from_str(include_str!("../🧫️fixtures/🔣️.json")).unwrap();
    let((mut original,snapshots,mutations),heap)=observe_heap_allocations_on_this_thread(||{
        let input=protocol::InputReplacement::Input {schema:String::with_capacity(law["unusedInputCapacity"].as_u64().unwrap()as usize),payload:Vec::with_capacity(law["unusedInputCapacity"].as_u64().unwrap()as usize)};
        let plan=HistoryReadPlan::new(Some(protocol::MutationId(law["originalTarget"].as_str().unwrap().into())),protocol::HistoryInputDrafts::from([(protocol::MutationId(law["originalTarget"].as_str().unwrap().into()),input)]),17,false);
        let original=Some(ArtifactDerivedHistoryPreview::<DemoSnapshot,DemoMutation> {plan:Some(plan),plan_retirement:None,drafts:protocol::HistoryInputDrafts::new(),target:None,cursor:0,operation:0,state:Some(Arc::new(DemoSnapshot {n:Some(law["snapshot"]["n"].as_i64().unwrap()as i32)})),progress:ReplayProgress::default(),registry:crate::os_store::SnapshotReadRegistryHandle::new(),generation:7,revision:[11;32],marker:PhantomData,finished:false});
        let snapshots:Arc<dyn ArtifactOwnedValueRetirementFactory<DemoSnapshot>>=Arc::new(OwnedValueRetirementFactory::<DemoSnapshot>::default());let mutations:Arc<dyn ArtifactOwnedValueRetirementFactory<DemoMutation>>=Arc::new(OwnedValueRetirementFactory::<DemoMutation>::default());(original,snapshots,mutations)
    });let held=heap.requested_bytes-heap.released_bytes;
    let identity=Arc::as_ptr(original.as_ref().unwrap().state.as_ref().unwrap());let registry=original.as_ref().unwrap().registry.identity();let plan_target=original.as_ref().unwrap().plan.as_ref().unwrap().target.as_ref().unwrap().0.as_ptr();
    let(bytes,heap)=observe_heap_allocations_on_this_thread(||history_read_retirement_birth_bytes::<DemoSnapshot,DemoMutation>());assert_eq!((heap.requested_bytes,heap.released_bytes),(0,0));assert!(bytes>0);
    let grant=RetainedCloneGrant {maximum_items:1,maximum_copy_bytes:0,maximum_capacity_bytes:bytes,maximum_release_bytes:0,maximum_depth:1};let mut frame=None;
    for (index,case) in law["grantCases"].as_array().unwrap().iter().enumerate() {
        let grant=match case.as_str().unwrap() {"zeroItems"=>RetainedCloneGrant {maximum_items:0,..grant},"belowCapacity"=>RetainedCloneGrant {maximum_capacity_bytes:bytes-1,..grant},"zeroDepth"=>RetainedCloneGrant {maximum_depth:0,..grant},"full"=>grant,_=>unreachable!()};
        let(result,heap)=observe_heap_allocations_on_this_thread(||admit_history_read_retirement(&mut original,&snapshots,&mutations,grant,|owner,preview|*owner.preview=Some(preview)));
        assert_eq!(usize::from(original.is_none()),law["expectedTransfers"][index].as_u64().unwrap()as usize);
        match result {Err(error)=>{assert!(matches!(error.kind,ValueRefusalKind::WorkLimit|ValueRefusalKind::OwnershipLimit|ValueRefusalKind::DepthLimit));assert_eq!((heap.requested_bytes,heap.released_bytes),(0,0));let original=original.as_ref().unwrap();assert_eq!(Arc::as_ptr(original.state.as_ref().unwrap()),identity);assert_eq!(original.registry.identity(),registry);assert_eq!(original.plan.as_ref().unwrap().target.as_ref().unwrap().0.as_ptr(),plan_target);},Ok(Some((owner,progress)))=>{assert_eq!(progress,RetainedCloneProgress {copied_items:1,retained_capacity_bytes:bytes,..Default::default()});assert_eq!((heap.requested_bytes,heap.released_bytes),(bytes,0));frame=Some(owner);},Ok(None)=>panic!("original preview is present")}
    }
    let(_,heap)=observe_heap_allocations_on_this_thread(||drop((snapshots,mutations)));assert_eq!((heap.requested_bytes,heap.released_bytes),(0,0));let(mut allocated,mut released)=(bytes,0);
    for turn in 0..200000 {
        let(demand,heap)=observe_heap_allocations_on_this_thread(||artifact_retirement_box_demands(frame.as_ref().unwrap(),3).unwrap());assert_eq!((heap.requested_bytes,heap.released_bytes),(0,0));let grant=RetainedCloneGrant {maximum_items:1,maximum_copy_bytes:3.max(demand.copy_bytes),maximum_capacity_bytes:demand.capacity_bytes,maximum_release_bytes:demand.release_bytes,maximum_depth:demand.depth};
        let(step,heap)=observe_heap_allocations_on_this_thread(||artifact_retirement_box_close_step(&mut frame,grant).unwrap());assert!(step.progress().fits(grant));assert_eq!(step.progress().retained_capacity_bytes,heap.requested_bytes,"birth turn{turn}");assert_eq!(step.progress().released_bytes,heap.released_bytes,"release turn{turn}");allocated+=heap.requested_bytes;released+=heap.released_bytes;if frame.is_none(){break;}assert!(turn<199999,"admitted history frame stalled");
    }
    assert_eq!(released,held+allocated);assert!(frame.is_none());let(_,heap)=observe_heap_allocations_on_this_thread(||drop((frame,original)));assert_eq!((heap.requested_bytes,heap.released_bytes),(0,0));
    println!("[DEBUG] actual history frame constructor refusal preserves original snapshot/registry/target pointers and empty8192 input backing0heap; exact admitted Box birth; original factories retained; full nested cleanup and frame release exact; terminal Drop0heap");
}

#[test]
fn history_read_retirement_preparation_keeps_original_before_paid_installation(){
 use super::prepare_history_read_retirement;use semio_framework_value::ErasedSnapshotRetirement;
 for body in [1,17,4096]{for cancel in [false,true]{
  let((mut original,snapshots,mutations),heap)=observe_heap_allocations_on_this_thread(||{
   let mut target=String::with_capacity(65536);target.push_str("original/α\0😀");let input=protocol::InputReplacement::Input{schema:String::with_capacity(8192),payload:Vec::with_capacity(65536)};let plan=HistoryReadPlan::new(Some(protocol::MutationId(target)),protocol::HistoryInputDrafts::from([(protocol::MutationId("original/🐚".into()),input)]),17,false);
   let original=Some(ArtifactDerivedHistoryPreview::<DemoSnapshot,DemoMutation>{plan:Some(plan),plan_retirement:None,drafts:protocol::HistoryInputDrafts::new(),target:None,cursor:0,operation:0,state:Some(Arc::new(DemoSnapshot{n:Some(23)})),progress:ReplayProgress::default(),registry:crate::os_store::SnapshotReadRegistryHandle::new(),generation:7,revision:[11;32],marker:PhantomData,finished:false});let snapshots:Arc<dyn ArtifactOwnedValueRetirementFactory<DemoSnapshot>>=Arc::new(OwnedValueRetirementFactory::<DemoSnapshot>::default());let mutations:Arc<dyn ArtifactOwnedValueRetirementFactory<DemoMutation>>=Arc::new(OwnedValueRetirementFactory::<DemoMutation>::default());(original,snapshots,mutations)
  });let held=heap.requested_bytes-heap.released_bytes;let pointer=original.as_ref().unwrap().plan.as_ref().unwrap().target.as_ref().unwrap().0.as_ptr();let bytes=history_read_retirement_birth_bytes::<DemoSnapshot,DemoMutation>();let grant=RetainedCloneGrant{maximum_items:1,maximum_capacity_bytes:bytes,maximum_depth:1,..Default::default()};
  for denied in [RetainedCloneGrant{maximum_items:0,..grant},RetainedCloneGrant{maximum_capacity_bytes:bytes-1,..grant},RetainedCloneGrant{maximum_depth:0,..grant}]{let(result,heap)=observe_heap_allocations_on_this_thread(||prepare_history_read_retirement(&snapshots,&mutations,denied).unwrap());assert!(result.is_none());assert_eq!((heap.requested_bytes,heap.released_bytes),(0,0));assert_eq!(Arc::strong_count(&snapshots),1);assert_eq!(original.as_ref().unwrap().plan.as_ref().unwrap().target.as_ref().unwrap().0.as_ptr(),pointer);}
  let((mut prepared,receipt),heap)=observe_heap_allocations_on_this_thread(||prepare_history_read_retirement(&snapshots,&mutations,grant).unwrap().unwrap());assert_eq!((heap.requested_bytes,heap.released_bytes),(bytes,0));assert_eq!(receipt.retained_capacity_bytes,bytes);assert_eq!(Arc::strong_count(&snapshots),2);assert!(original.is_some());let metadata=RetainedCloneGrant{maximum_items:1,maximum_depth:1,..Default::default()};
  for _ in 0..16{for denied in [RetainedCloneGrant{maximum_items:0,..metadata},RetainedCloneGrant{maximum_depth:0,..metadata}]{let(receipt,heap)=observe_heap_allocations_on_this_thread(||prepared.install_preview(&mut original,denied).unwrap());assert!(receipt.is_none());assert_eq!((heap.requested_bytes,heap.released_bytes),(0,0));assert_eq!(original.as_ref().unwrap().plan.as_ref().unwrap().target.as_ref().unwrap().0.as_ptr(),pointer);}}
  prepared.bind_registry(original.as_ref().unwrap().registry.identity().wrapping_add(1));let(error,heap)=observe_heap_allocations_on_this_thread(||prepared.install_preview(&mut original,metadata).unwrap_err());assert_eq!(error.kind,ValueRefusalKind::InvariantViolated);assert_eq!((heap.requested_bytes,heap.released_bytes),(0,0));assert_eq!(original.as_ref().unwrap().plan.as_ref().unwrap().target.as_ref().unwrap().0.as_ptr(),pointer);prepared.bind_registry(original.as_ref().unwrap().registry.identity());let(step,heap)=observe_heap_allocations_on_this_thread(||prepared.close_step(RetainedCloneGrant::default()).unwrap());assert_eq!(step.progress(),Default::default());assert_eq!((heap.requested_bytes,heap.released_bytes),(0,0));
  if !cancel{let(receipt,heap)=observe_heap_allocations_on_this_thread(||prepared.install_preview(&mut original,metadata).unwrap().unwrap());assert_eq!(receipt.copied_items,1);assert_eq!((heap.requested_bytes,heap.released_bytes),(0,0));assert!(original.is_none());}
  let mut frame=None;if !cancel{let((owner,receipt),heap)=observe_heap_allocations_on_this_thread(||prepared.take_retirement(metadata).unwrap().unwrap());assert_eq!(receipt.copied_items,1);assert_eq!((heap.requested_bytes,heap.released_bytes),(0,0));frame=Some(owner);}let mut issuers=Some((snapshots,mutations));if !cancel{let(_,heap)=observe_heap_allocations_on_this_thread(||drop(issuers.take()));assert_eq!((heap.requested_bytes,heap.released_bytes),(0,0));}let mut births=bytes;let mut release=0;
  for turn in 0..200000{let demand=if cancel{semio_framework_value::RetirementDemand{copy_bytes:prepared.next_copy_byte_demand().unwrap(),capacity_bytes:prepared.next_capacity_byte_demand(body).unwrap(),release_bytes:prepared.next_release_byte_demand().unwrap(),depth:prepared.next_depth_demand().unwrap()}}else{artifact_retirement_box_demands(frame.as_ref().unwrap(),body).unwrap()};let grant=RetainedCloneGrant{maximum_items:1,maximum_copy_bytes:body.max(demand.copy_bytes),maximum_capacity_bytes:demand.capacity_bytes,maximum_release_bytes:demand.release_bytes,maximum_depth:demand.depth};let(step,heap)=observe_heap_allocations_on_this_thread(||if cancel{prepared.close_step(grant).unwrap()}else{artifact_retirement_box_close_step(&mut frame,grant).unwrap()});assert!(step.progress().fits(grant));assert_eq!((heap.requested_bytes,heap.released_bytes),(step.progress().retained_capacity_bytes,step.progress().released_bytes));births+=heap.requested_bytes;release+=heap.released_bytes;if cancel&&turn==0{let(error,heap)=observe_heap_allocations_on_this_thread(||prepared.install_preview(&mut original,metadata).unwrap_err());assert_eq!(error.kind,ValueRefusalKind::InvariantViolated);assert_eq!((heap.requested_bytes,heap.released_bytes),(0,0));assert_eq!(original.as_ref().unwrap().plan.as_ref().unwrap().target.as_ref().unwrap().0.as_ptr(),pointer);}if cancel&&prepared.terminal_is_empty()||!cancel&&frame.is_none(){break}assert!(turn<199999);}
  if cancel{assert_eq!(original.as_ref().unwrap().plan.as_ref().unwrap().target.as_ref().unwrap().0.as_ptr(),pointer);let(snapshots,mutations)=issuers.as_ref().unwrap();let((owner,_),heap)=observe_heap_allocations_on_this_thread(||admit_history_read_retirement(&mut original,snapshots,mutations,RetainedCloneGrant{maximum_items:1,maximum_capacity_bytes:bytes,maximum_depth:1,..Default::default()},|owner,preview|*owner.preview=Some(preview)).unwrap().unwrap());births+=heap.requested_bytes;assert_eq!(heap.released_bytes,0);let(_,heap)=observe_heap_allocations_on_this_thread(||drop(issuers.take()));assert_eq!((heap.requested_bytes,heap.released_bytes),(0,0));let mut cleanup=Some(owner);while cleanup.is_some(){let demand=artifact_retirement_box_demands(cleanup.as_ref().unwrap(),body).unwrap();let grant=RetainedCloneGrant{maximum_items:1,maximum_copy_bytes:body.max(demand.copy_bytes),maximum_capacity_bytes:demand.capacity_bytes,maximum_release_bytes:demand.release_bytes,maximum_depth:demand.depth};let(step,heap)=observe_heap_allocations_on_this_thread(||artifact_retirement_box_close_step(&mut cleanup,grant).unwrap());assert!(step.progress().fits(grant));assert_eq!((heap.requested_bytes,heap.released_bytes),(step.progress().retained_capacity_bytes,step.progress().released_bytes));births+=heap.requested_bytes;release+=heap.released_bytes;}}
  assert_eq!(release,held+births);
  let(_,heap)=observe_heap_allocations_on_this_thread(||drop((prepared,frame,original)));assert_eq!((heap.requested_bytes,heap.released_bytes),(0,0));eprintln!("[DEBUG] Native prepared history frame body={body} cancel={cancel} original={held} sixteenDeniedInstallations=unchanged birth={births} release={release} terminalDrop=0");
 }}
}
